import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

good_numbers = set()
max_limit = 50 # Setting a practical limit for search space

for x in range(2, max_limit):
    for y in range(x + 1, max_limit):
        if gcd(x, y) > 1:
            m = x**2 + y**2
            good_numbers.add(m)

sorted_good_numbers = sorted(list(good_numbers))

# We need the 20th smallest, which is at index 19
if len(sorted_good_numbers) >= 20:
    print(sorted_good_numbers[19])
else:
    print(f"Found only {len(sorted_good_numbers)} numbers.")

