import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_good_numbers(limit):
    m_values = set()
    # Search for x < y such that gcd(x, y) > 1
    for x in range(1, limit + 1):
        for y in range(x + 1, limit + 1):
            if gcd(x, y) > 1:
                m = x**2 + y**2
                m_values.add(m)

    sorted_m = sorted(list(m_values))
    return sorted_m

# Search up to a limit where the 20th element is likely contained. 
# Since W4 found 208, a limit of 20 should be sufficient.
limit = 20 
candidates = find_good_numbers(limit)

if len(candidates) >= 20:
    twentieth = candidates[19]
    print(f"Total candidates found up to limit {limit}: {len(candidates)}")
    print(f"The 20th smallest candidate is: {twentieth}")
    print(f"The first 25 candidates are: {candidates[:25]}")
else:
    print(f"Only found {len(candidates)} candidates up to limit {limit}.")

